using System.Net.Http.Headers;
using System.Text.Json.Nodes;
using System.Threading.RateLimiting;
var builder=WebApplication.CreateBuilder(args);
builder.Logging.ClearProviders(); // OAuth callback query strings must never be logged.
builder.WebHost.UseUrls("http://0.0.0.0:"+(Environment.GetEnvironmentVariable("PORT")??"8080"));
builder.Services.AddRateLimiter(o=>{o.RejectionStatusCode=429;o.GlobalLimiter=PartitionedRateLimiter.Create<HttpContext,string>(c=>RateLimitPartition.GetFixedWindowLimiter(c.Connection.RemoteIpAddress?.ToString()??"unknown",_=>new(){PermitLimit=300,Window=TimeSpan.FromMinutes(1),QueueLimit=0}));});
var app=builder.Build();app.UseRateLimiter();var store=new SessionStore();
var publicUrl=Environment.GetEnvironmentVariable("PUBLIC_URL")??"";
if(string.IsNullOrWhiteSpace(publicUrl))publicUrl=Environment.GetEnvironmentVariable("RENDER_EXTERNAL_URL")??"";
if(!Uri.TryCreate(publicUrl,UriKind.Absolute,out var publicUri)||publicUri.Scheme!="https"||publicUri.AbsolutePath!="/"||publicUri.Query.Length>0||publicUri.Fragment.Length>0||publicUri.UserInfo.Length>0)throw new Exception("PUBLIC_URL debe ser el origen HTTPS del alojamiento");
publicUrl=publicUrl.TrimEnd('/');
string Env(string key)=>Environment.GetEnvironmentVariable(key)??"";
string Id(string provider)=>Env(provider=="facebook"?"META_APP_ID":"GOOGLE_CLIENT_ID");
string Secret(string provider)=>Env(provider=="facebook"?"META_APP_SECRET":"GOOGLE_CLIENT_SECRET");
string Version()=>System.Text.RegularExpressions.Regex.IsMatch(Env("META_API_VERSION"),@"^v\d{1,2}\.0$")?Env("META_API_VERSION"):"v26.0";
bool Ready(string p)=>Id(p).Length>0&&Secret(p).Length>0;
using var http=new HttpClient(new SocketsHttpHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(25)};
async Task<JsonObject> Call(string url,string token="",Dictionary<string,string>? form=null){using var request=new HttpRequestMessage(form==null?HttpMethod.Get:HttpMethod.Post,url);if(token.Length>0)request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);if(form!=null)request.Content=new FormUrlEncodedContent(form);using var response=await http.SendAsync(request);var text=await response.Content.ReadAsStringAsync();if(!response.IsSuccessStatusCode)throw new Exception("El proveedor rechazó la autorización. Revisá los permisos o volvé a autorizar.");return JsonNode.Parse(text)?.AsObject()??throw new Exception("El proveedor no respondió correctamente");}
string Redirect(string p)=>publicUrl+"/callback/"+p;
string Query(Dictionary<string,string> values)=>string.Join("&",values.Select(v=>Uri.EscapeDataString(v.Key)+"="+Uri.EscapeDataString(v.Value)));
app.Use(async(c,next)=>{c.Response.Headers["Cache-Control"]="no-store";c.Response.Headers["Referrer-Policy"]="no-referrer";c.Response.Headers["Content-Security-Policy"]="default-src 'none'; frame-ancestors 'none'; base-uri 'none'";try{await next();}catch{c.Response.StatusCode=400;await c.Response.WriteAsJsonAsync(new{error="La conexión no se completó. Volvé a OBS Control e intentá nuevamente."});}});
app.MapGet("/",()=>Results.Text("OBS Control · servicio de autorización. No recibe ni transmite video."));
app.MapGet("/capabilities",()=>new{protocol=1,facebook=Ready("facebook"),google=Ready("google")});
app.MapPost("/sessions",(StartRequest input)=>{if(!Ready(input.Provider))return Results.Json(new{error="El administrador todavía no habilitó esta plataforma"},statusCode:503);var(id,s)=store.Create(input.Provider,input.Kind,input.Challenge);var fields=new Dictionary<string,string>{{"client_id",Id(input.Provider)},{"redirect_uri",Redirect(input.Provider)},{"response_type","code"},{"state",id}};string auth;if(input.Provider=="facebook"){fields["scope"]=s.Kind=="profile"?"public_profile,publish_video":"public_profile,pages_show_list,pages_read_engagement,pages_manage_posts";auth="https://www.facebook.com/"+Version()+"/dialog/oauth?";}else{fields["scope"]="https://www.googleapis.com/auth/youtube.force-ssl";fields["access_type"]="offline";fields["prompt"]="consent";fields["code_challenge"]=SessionStore.Challenge(s.OAuthVerifier);fields["code_challenge_method"]="S256";auth="https://accounts.google.com/o/oauth2/v2/auth?";}return Results.Ok(new{id,url=auth+Query(fields)});});
app.MapPost("/sessions/{id}/redeem",(string id,RedeemRequest input)=>{var result=store.Redeem(id,input.Verifier);return Results.Ok(new{status=result.Status,grant=result.Grant});});
app.MapGet("/callback/{provider}",async(string provider,HttpContext c)=>{var state=c.Request.Query["state"].ToString();var s=store.Claim(state,provider);try{if(c.Request.Query.ContainsKey("error")||string.IsNullOrEmpty(c.Request.Query["code"]))throw new Exception("No se concedieron los permisos");var fields=new Dictionary<string,string>{{"client_id",Id(provider)},{"client_secret",Secret(provider)},{"code",c.Request.Query["code"].ToString()},{"redirect_uri",Redirect(provider)}};JsonObject grant;
if(provider=="facebook"){var token=await Call("https://graph.facebook.com/"+Version()+"/oauth/access_token",form:fields);var access=token["access_token"]!.GetValue<string>();var me=await Call("https://graph.facebook.com/"+Version()+"/me?fields=id,name",access);var pages=new JsonArray();if(s.Kind=="page"){var result=await Call("https://graph.facebook.com/"+Version()+"/me/accounts?fields=id,name,access_token&limit=100",access);pages=result["data"]?.DeepClone().AsArray()??new();}grant=new(){["provider"]="facebook",["kind"]=s.Kind,["accessToken"]=access,["userId"]=me["id"]!.GetValue<string>(),["name"]=me["name"]?.GetValue<string>()??"Facebook",["pages"]=pages,["apiVersion"]=Version()};}
else{fields["grant_type"]="authorization_code";fields["code_verifier"]=s.OAuthVerifier;var token=await Call("https://oauth2.googleapis.com/token",form:fields);var access=token["access_token"]!.GetValue<string>();var channel=await Call("https://www.googleapis.com/youtube/v3/channels?part=id,snippet&mine=true",access);var item=channel["items"]?.AsArray().FirstOrDefault()??throw new Exception("La cuenta no tiene un canal YouTube");if(string.IsNullOrEmpty(token["refresh_token"]?.GetValue<string>()))throw new Exception("Google no entregó autorización renovable");grant=new(){["provider"]="google",["accessToken"]=access,["refreshToken"]=token["refresh_token"]!.GetValue<string>(),["expiresIn"]=token["expires_in"]?.GetValue<int>()??3600,["name"]=item["snippet"]?["title"]?.GetValue<string>()??"YouTube"};}
store.Finish(state,grant);return Results.Content("<!doctype html><meta charset=utf-8><title>Cuenta autorizada</title><h1>Cuenta autorizada</h1><p>Volvé a OBS Control. La conexión se completará allí. Podés cerrar esta pestaña.</p>","text/html; charset=utf-8");
}catch{store.Finish(state,null,"El proveedor no completó la autorización. Revisá los permisos o volvé a autorizar.");return Results.Content("<!doctype html><meta charset=utf-8><title>Conexión pendiente</title><h1>No se pudo conectar</h1><p>Volvé a OBS Control e intentá de nuevo. No se inició ninguna transmisión.</p>","text/html; charset=utf-8");}});
app.MapPost("/google/refresh",async(RefreshRequest input)=>{if(!Ready("google")||input.RefreshToken.Length is <10 or >4096)return Results.BadRequest(new{error="Autorización inválida"});var result=await Call("https://oauth2.googleapis.com/token",form:new(){{"client_id",Id("google")},{"client_secret",Secret("google")},{"refresh_token",input.RefreshToken},{"grant_type","refresh_token"}});return Results.Ok(new{access_token=result["access_token"]!.GetValue<string>(),expires_in=result["expires_in"]?.GetValue<int>()??3600});});
app.Run();
record StartRequest(string Provider,string Kind,string Challenge);
record RedeemRequest(string Verifier);
record RefreshRequest(string RefreshToken);
